/* Guide search and pagination are independent from the booking inventory. */
(()=>{'use strict';
 const root=document.querySelector('[data-journal]');if(!root)return;
 const $=s=>root.querySelector(s), cards=[...root.querySelectorAll('[data-journal-card]')];
 const search=$('[data-journal-search]'),topic=$('[data-journal-rubric]'),hotel=$('[data-journal-hotel]'),library=$('#guide-library'),pages=$('[data-journal-pages]'),more=$('[data-journal-more]');
 const normalize=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е');let page=1,expanded=false,firstPage=1;
 const options=select=>[...select.options].map(x=>x.value);
 function readURL(){const q=new URLSearchParams(location.search);search.value=q.get('q')||'';topic.value=options(topic).includes(q.get('topic'))?q.get('topic'):root.dataset.rubric;hotel.value=options(hotel).includes(q.get('near'))?q.get('near'):'all';page=Math.max(1,parseInt(q.get('page'),10)||1);expanded=q.get('more')==='1';firstPage=Math.max(1,Math.min(page,parseInt(q.get('from'),10)||1));}
 function writeURL(){const q=new URLSearchParams(location.search);for(const k of ['q','topic','near','page','more','from'])q.delete(k);if(search.value.trim())q.set('q',search.value.trim());if(topic.value!==root.dataset.rubric)q.set('topic',topic.value);if(hotel.value!=='all')q.set('near',hotel.value);if(page>1)q.set('page',page);if(expanded){q.set('more','1');if(firstPage>1)q.set('from',firstPage);}history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+location.hash);}
 function render(write=true){const terms=normalize(search.value.trim()).split(/\s+/).filter(Boolean);const list=cards.filter(card=>(topic.value==='all'||card.dataset.rubric===topic.value)&&(hotel.value==='all'||card.dataset.hotels.split(' ').includes(hotel.value))&&terms.every(t=>normalize(card.dataset.search).includes(t)));const total=Math.ceil(list.length/6);page=Math.max(1,Math.min(page,total||1));const shown=list.slice(expanded?(firstPage-1)*6:(page-1)*6,page*6);cards.forEach(card=>card.hidden=!shown.includes(card));$('[data-journal-empty]').hidden=!!list.length;$('[data-journal-count]').textContent='Показано '+shown.length+' из '+list.length+' материалов';$('[data-journal-pagination]').hidden=!list.length||total<=1;more.hidden=page>=total;
 pages.replaceChildren();for(let n=1;n<=total;n++){const button=document.createElement('button');button.type='button';button.textContent=n;button.dataset.page=n;button.setAttribute('aria-label','Страница '+n);if(n===page)button.setAttribute('aria-current','page');pages.append(button);}if(total>1){const next=document.createElement('button');next.type='button';next.textContent='→';next.dataset.page=Math.min(total,page+1);next.disabled=page>=total;next.setAttribute('aria-label','Следующая страница');pages.append(next);}
 root.querySelectorAll('[data-journal-topic]').forEach(a=>{if(a.dataset.journalTopic===topic.value)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});if(write)writeURL();
 }
 function reset(){search.value='';topic.value=root.dataset.rubric;hotel.value='all';page=1;expanded=false;render();}
 search.addEventListener('input',()=>{page=1;expanded=false;render();});
 topic.addEventListener('change',()=>{if(root.dataset.rubric!=='all'&&topic.value!==root.dataset.rubric){const q=new URLSearchParams({topic:topic.value,q:search.value,near:hotel.value});location.href=(window.SITE_BASE||'')+'/blog/?'+q+'#guide-library';return;}page=1;expanded=false;render();});
 hotel.addEventListener('change',()=>{page=1;expanded=false;render();if(hotel.value!=='all')map.dispatchEvent(new CustomEvent('hotel-map-select',{detail:{id:hotel.value,pan:false}}));});
 $('[data-journal-reset]').addEventListener('click',()=>{reset();search.focus({preventScroll:true});});$('[data-journal-clear]').addEventListener('click',()=>{reset();search.focus();});
 root.querySelectorAll('[data-journal-topic]').forEach(a=>a.addEventListener('click',ev=>{if(root.dataset.rubric!=='all'||ev.ctrlKey||ev.metaKey||ev.shiftKey)return;ev.preventDefault();topic.value=a.dataset.journalTopic;page=1;expanded=false;render();library.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});library.focus({preventScroll:true});}));
 pages.addEventListener('click',ev=>{const button=ev.target.closest('[data-page]');if(!button||button.disabled)return;page=Number(button.dataset.page);expanded=false;render();library.scrollIntoView({block:'start',behavior:'instant'});pages.querySelector('[aria-current]')?.focus({preventScroll:true});});
 more.addEventListener('click',()=>{if(!expanded)firstPage=page;page++;expanded=true;render();if(more.hidden)pages.querySelector('[aria-current]')?.focus({preventScroll:true});});
 addEventListener('popstate',()=>{readURL();render(false);});readURL();render(false);
 const map=$('[data-hotel-map]'),form=$('[data-booking]'),expand=$('[data-journal-map-expand]'),stage=map.querySelector('.map-stage');
 function syncMap(){map.querySelectorAll('[data-map-select]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.mapSelect===map.dataset.selected)));}
 new MutationObserver(syncMap).observe(map,{attributes:true,attributeFilter:['data-selected']});syncMap();
 map.addEventListener('hotel-map-selection',ev=>{if(form.elements.hotel.value!==ev.detail.id){form.elements.hotel.value=ev.detail.id;form.elements.hotel.dispatchEvent(new Event('change',{bubbles:true}));}});
 function syncBooking(){const h=form.elements.hotel.value;if(h)map.dispatchEvent(new CustomEvent('hotel-map-select',{detail:{id:h,pan:false}}));if(!form.elements.checkin.value)form.querySelector('[data-date-label]').textContent='Выберите даты';}
 document.addEventListener('booking-context-change',syncBooking);syncBooking();
 function expandedMap(value){map.classList.toggle('jr-map-expanded',value);document.body.classList.toggle('jr-map-open',value);expand.setAttribute('aria-expanded',String(value));expand.setAttribute('aria-label',value?'Свернуть карту':'Развернуть карту');stage.setAttribute('role',value?'dialog':'region');stage.setAttribute('aria-label','Карта отелей Москвы');if(value)stage.setAttribute('aria-modal','true');else stage.removeAttribute('aria-modal');map.dispatchEvent(new Event('hotel-map-show'));expand.focus();}
 expand.addEventListener('click',()=>expandedMap(!map.classList.contains('jr-map-expanded')));document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&map.classList.contains('jr-map-expanded'))expandedMap(false);});stage.addEventListener('keydown',ev=>{if(ev.key!=='Tab'||!map.classList.contains('jr-map-expanded'))return;const buttons=[...stage.querySelectorAll('button,a,[tabindex="0"]')].filter(e=>e.getClientRects().length);if(ev.shiftKey&&document.activeElement===buttons[0]){ev.preventDefault();buttons.at(-1).focus();}else if(!ev.shiftKey&&document.activeElement===buttons.at(-1)){ev.preventDefault();buttons[0].focus();}});
 if(!matchMedia('(prefers-reduced-motion:reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('jr-enter');observer.unobserve(entry.target);}}),{threshold:.08});root.querySelectorAll('.jr-card,.jr-map-band,.jr-extra,.jr-booking').forEach(e=>observer.observe(e));}
})();
